import { Router } from "express";
import {
  exportFarmers,
  getFarmerById,
  getFarmers,
  createFarmer,
  updateFarmer,
  deleteFarmer,
  createInputAllocation,
  updateInputAllocationStatus,
  getCropRecords,
  createCropRecord,
  updateCropRecord,
} from "../controllers/farmers.controller";
import { auditRequest } from "../middleware/auditRequest";

const router = Router();

router.get("/export", exportFarmers);
router.get("/crop-records", getCropRecords);
router.get("/", getFarmers);
router.get("/:id", getFarmerById);

// CRUD
router.post("/", auditRequest("create", "farmer"), createFarmer);
router.put("/:id", auditRequest("update", "farmer"), updateFarmer);
router.delete("/:id", auditRequest("delete", "farmer"), deleteFarmer);

// Allocations
router.post("/:id/allocations", auditRequest("create", "input_allocation"), createInputAllocation);
router.patch(
  "/:id/allocations/:allocationId",
  auditRequest("update", "input_allocation"),
  updateInputAllocationStatus
);

// Crop records
router.post("/:id/crop-records", auditRequest("create", "crop_record"), createCropRecord);
router.put("/crop-records/:recordId", auditRequest("update", "crop_record"), updateCropRecord);

export default router;
